{"cards": [{"node_code": "N_780308bb55f18b35", "definition": "颈椎疾病是脊柱外科中专门针对颈椎（C1-C7）及其附属结构（椎间盘、韧带、神经根、脊髓）的退变、创伤、畸形及肿瘤等病理状态的诊断与治疗。", "boundary": "本节点聚焦于颈椎区域的特异性病变。包括颈椎病（神经根型、脊髓型、椎动脉型等）、颈椎骨折脱位、颈椎间盘突出及颈椎肿瘤。与腰椎疾病的区别在于解剖部位不同，颈椎涉及上肢神经支配及椎动脉供血；与脊柱畸形的区别在于本节点侧重后天退变或创伤，畸形侧重先天性或发育性结构异常。", "includes": ["各型颈椎病的临床诊疗", "颈椎创伤、骨折与脱位", "颈椎间盘突出与神经压迫"], "excludes": ["胸椎及腰椎病变（归入相应节段或脊柱外科其他分支）", "先天性颈椎融合或畸形（归入脊柱畸形）"], "sibling_distinctions": [{"other_code": "N_8292852a4a435b39", "rule": "颈椎疾病处理C1-C7节段的病变，涉及上肢神经及椎动脉；腰椎疾病处理L1-L5节段病变，主要涉及下肢神经及马尾。"}, {"other_code": "N_3ea1a9c22b5af914", "rule": "颈椎疾病侧重后天性退变、创伤或肿瘤；脊柱畸形侧重先天性或发育性的脊柱结构异常（如先天性斜颈、半椎体）。"}], "cross_boundary_rule": "颈椎部位的退变、创伤、肿瘤归入颈椎疾病；若为先天性颈椎结构异常归入脊柱畸形；若为全身性代谢性骨病累及颈椎，主挂载仍为颈椎疾病，可关联骨病。"}, {"node_code": "N_8292852a4a435b39", "definition": "腰椎疾病是脊柱外科中专门针对腰椎（L1-L5）及骶椎相关结构的退变、创伤、畸形及肿瘤等病理状态的诊断与治疗，重点解决下腰痛及下肢神经症状。", "boundary": "本节点聚焦于腰椎区域的特异性病变。包括腰椎间盘突出症、腰椎管狭窄症、腰椎滑脱、腰椎骨折及腰椎肿瘤。与颈椎疾病的区别在于解剖部位及神经支配区域不同；与脊柱畸形的区别在于本节点侧重后天退变或创伤，畸形侧重先天性结构异常。", "includes": ["腰椎间盘突出与腰椎管狭窄", "腰椎滑脱与腰椎骨折", "腰椎肿瘤与感染"], "excludes": ["颈椎及胸椎病变（归入相应节段）", "先天性腰椎融合或畸形（归入脊柱畸形）"], "sibling_distinctions": [{"other_code": "N_780308bb55f18b35", "rule": "腰椎疾病处理L1-L5节段病变，主要涉及下肢神经及马尾；颈椎疾病处理C1-C7节段病变，涉及上肢神经及椎动脉。"}, {"other_code": "N_3ea1a9c22b5af914", "rule": "腰椎疾病侧重后天性退变、创伤或肿瘤；脊柱畸形侧重先天性或发育性的脊柱结构异常。"}], "cross_boundary_rule": "腰椎部位的退变、创伤、肿瘤归入腰椎疾病；若为先天性腰椎结构异常归入脊柱畸形；若为全身性代谢性骨病累及腰椎，主挂载仍为腰椎疾病。"}, {"node_code": "N_3ea1a9c22b5af914", "definition": "脊柱畸形是脊柱外科中研究脊柱先天性或发育性结构异常的分支，涵盖脊柱侧弯、后凸畸形、先天性融合、半椎体及神经肌肉性脊柱侧弯等。", "boundary": "本节点聚焦于脊柱形态学的结构性异常，无论其累及颈椎、胸椎或腰椎。包括特发性脊柱侧弯、先天性脊柱畸形、神经肌肉性侧弯及脊柱后凸畸形。与颈椎/腰椎疾病的区别在于，本节点侧重整体脊柱力线与形态矫正，而非单一节段的退变或创伤；与脊柱感染与肿瘤的区别在于本节点侧重非感染性、非肿瘤性的结构异常。", "includes": ["特发性与先天性脊柱侧弯", "脊柱后凸畸形（如驼背）", "神经肌肉性脊柱侧弯"], "excludes": ["后天性退变导致的脊柱不稳（归入颈椎/腰椎疾病）", "脊柱感染或肿瘤导致的病理性畸形（归入脊柱感染与脊柱肿瘤）"], "sibling_distinctions": [{"other_code": "N_780308bb55f18b35", "rule": "脊柱畸形侧重整体脊柱力线及形态矫正（如侧弯、后凸）；颈椎疾病侧重颈椎节段的退变、创伤或神经压迫。"}, {"other_code": "N_8292852a4a435b39", "rule": "脊柱畸形侧重整体脊柱力线及形态矫正；腰椎疾病侧重腰椎节段的退变、创伤或神经压迫。"}], "cross_boundary_rule": "先天性或发育性脊柱结构异常（如侧弯、后凸）归入脊柱畸形；后天性退变、创伤或肿瘤导致的局部病变归入颈椎/腰椎疾病或脊柱感染与肿瘤。"}]}
